    // Check if directory exists
    struct stat dirStat;
    if (stat(directory.c_str(), &dirStat) != 0) {
        std::cerr << "Directory does not exist: " << directory << std::endl;
        return;
    }

    // Check if directory is writable
    if (!(dirStat.st_mode & S_IWUSR)) {
        std::cerr << "Directory is not writable by the current user: " << directory << std::endl;
        return;
    }

    // Create the file
    int fd = open(fullPath.c_str(), O_WRONLY | O_CREAT | O_TRUNC, S_IRUSR | S_IWUSR);
    if (fd == -1) {
        std::cerr << "Failed to open/create file: " << fullPath << std::endl;
        return;
    }

    // Write content to the file
    ssize_t bytesWritten = write(fd, content.c_str(), content.size());
